command:
// ==========================================
// LUNAS WIRKUNG: SCHWARZE KATZE (APHASMA)
//
// - ALLE gültigen Lebewesen im Target innerhalb von 4 Schritt (kein Ziel-Limit)
// - nutzt direkt DSK.Wesen.IstLebendig aus Block 2.3 des Frameworks
// - Schips-Verlust: QS / 2 (kaufmännisch gerundet), gedeckelt auf vorhandene Schips
//   (hat ein Ziel z. B. 1 Schip bei 2 Abzug, verliert es diesen 1 Schip; nur 0 Schips = Misserfolg)
// - system.stats.schips.gearmodifier, Modus 2
// - Dauer: Bis zur nächsten Toten Mada
// - gespeicherte Ziele | GM-Button | Framework-Effektanlage
// ==========================================

(async function () {
    const macroUuid = this?.uuid || game.macros.getName("Schwarze Katze")?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++
    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
        !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
        !globalThis.DSK?.Wesen?.IstLebendig || !globalThis.DSK?.Geometrie?.Distanz ||
        !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
        !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
        !globalThis.DSK?.GabenUI?.GMMakroButton ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;
    if (
        !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
        !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
        !DSK_FW?.Wesen?.IstLebendig || !DSK_FW?.Geometrie?.Distanz ||
        !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
        !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
        !DSK_FW?.GabenUI?.GMMakroButton ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
        !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++
    const gabenName = "Schwarze Katze", vollerName = "Schwarze Katze (Aphasma)", ahne = "Aphasma";
    const flagKey = "pendingSchwarzeKatzeAphasma", endeKey = "aphasmaSchwarzeKatze";
    const endeText = "Der Fluch der Schwarzen Katze bricht. Das Pech weicht von diesem Wesen.";
    const dauerText = "Bis zur nächsten Toten Mada";

    DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

    // +++ 3 - HELFER ++++++++++++++++++++++++++++++++++++++++++++++
    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
        if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
    };

    const ladeActor = async uuid => {
        if (!uuid) return null;
        try {
            const doc = await fromUuid(uuid);
            return doc?.documentName === "Token" ? doc.actor : doc || null;
        } catch (error) {
            console.warn("Schwarze Katze: Actor konnte nicht geladen werden.", { uuid, error });
            return null;
        }
    };

    // Nutzt direkt Block 2.3 des Frameworks (inkl. Elementar-Ausschluss)
    const istLebewesen = actor => DSK_FW.Wesen.IstLebendig(actor, { zusaetzlichAusgeschlossen: ["elementar"] });

    // Findet bestehende Schwarze-Katze-Effekte (auch aus älteren Makro-Versionen ohne casterUuid)
    const findeEigeneEffekte = (actor, casterUuid = null) =>
        (actor?.effects || []).filter(e => {
            const namePasst = (e.name || e.label || "") === vollerName;
            if (!namePasst) return false;
            const effectCaster = e.getFlag("dsk", "casterUuid");
            return !casterUuid || !effectCaster || effectCaster === casterUuid;
        });

    // Liest die aktuell verfügbaren Schips des Ziels aus (rechnet einen evtl. bereits aktiven Effekt desselben Wirkenden heraus)
    const leseVerfuegbareSchips = (actor, casterUuid = null) => {
        if (!actor) return 0;

        let eigenAbzug = 0;
        for (const eff of findeEigeneEffekte(actor, casterUuid)) {
            for (const ch of eff.changes || []) {
                if (ch.key === "system.stats.schips.gearmodifier") {
                    eigenAbzug += Math.abs(Number(ch.value) || 0);
                }
            }
        }

        const schips = foundry.utils.getProperty(actor, "system.stats.schips") || {};
        const value = Number(schips.value);
        const max = Number(schips.max);

        // Im DSK-System ist system.stats.schips.value der aktuelle Stand verfügbarer Schips.
        // Falls value durch einen bestehenden eigenen Effekt auf 0 gedrückt wurde, addieren wir eigenAbzug wieder drauf.
        if (Number.isFinite(value)) {
            const verfuegbar = value + eigenAbzug;
            return Math.max(0, Number.isFinite(max) && max > 0 ? Math.min(max, verfuegbar) : verfuegbar);
        }

        return 0;
    };

    const beschreibungFuer = (casterName, qs, schipVerlust) =>
        `<b>${casterName}</b> bringt schreckliches Pech!` +
        `<br><br>Das Schicksal wendet sich von den anvisierten Lebewesen ab.` +
        `<br>• <b>Verlust von Schicksalspunkten:</b> −${schipVerlust} Schips (bzw. alle übrigen, falls weniger vorhanden)` +
        `<br>• <b>Berechnung:</b> ${qs} QS / 2, kaufmännisch gerundet` +
        `<br><br><b>Reichweite:</b> 4 Schritt | <b>Zielkategorie:</b> Lebewesen`;

    // +++ 4 - EFFEKT ANWENDEN +++++++++++++++++++++++++++++++++++++
    const wendeEffekteAn = async ({ casterActor, targetActor, qs, tatsaechlicherVerlust }) => {
        if (!casterActor || !targetActor || !istLebewesen(targetActor)) return false;

        const verlust = Math.max(1, Math.floor(Number(tatsaechlicherVerlust) || 1));

        const zielAlt = findeEigeneEffekte(targetActor, casterActor.uuid);
        if (zielAlt.length) {
            await targetActor.deleteEmbeddedDocuments("ActiveEffect", zielAlt.map(e => e.id));
        }

        const zielEffekt = await DSK_FW.Effekt.Anwenden({
            name: vollerName,
            ahne,
            beschreibung:
                `Das Pech klebt an den Pfoten dieses Lebewesens.` +
                `<br><br><b>Schicksalspunkte:</b> −${verlust} Schips` +
                `<br><b>Wirkungsdauer:</b> ${dauerText}`,
            gabeZiel: "",
            qs,
            skills: ["system.stats.schips.gearmodifier"],
            key: "direkterSystemwert",
            formel: String(-verlust),
            ziel: targetActor,
            showIcon: 1,
            flags: {
                core: { statusId: "downgrade" },
                dsk: {
                    isSchwarzeKatze: true,
                    casterUuid: casterActor.uuid,
                    qs,
                    schipVerlust: verlust,
                    wirkungsende: {
                        sfName: endeKey,
                        basisEffektName: vollerName,
                        beschreibungFuerEnde: endeText
                    }
                }
            }
        });

        if (!zielEffekt) return false;

        const zielEnde = zielEffekt.getFlag("dsk", "wirkungsende");
        const korrekterSystemwert = (zielEffekt.changes || []).some(change =>
            change.key === "system.stats.schips.gearmodifier" &&
            Number(change.mode) === 2 &&
            Number(change.value) === -verlust
        );

        return Boolean(
            zielEffekt.parent?.uuid === targetActor.uuid &&
            zielEffekt.getFlag("dsk", "isSchwarzeKatze") === true &&
            zielEffekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
            Number(zielEffekt.getFlag("dsk", "schipVerlust")) === verlust &&
            zielEnde?.sfName === endeKey &&
            korrekterSystemwert
        );
    };

    // +++ 5 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++++++
    const verarbeiteAnfrage = async (casterActor, daten) => {
        if (!game.user.isGM || !casterActor || !daten) return false;

        if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) {
            ui.notifications.warn("Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum Wirkenden.");
            return false;
        }

        if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
            ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
            return false;
        }

        const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
        const schipVerlust = Math.max(1, Math.round(qs / 2));
        const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
        const erfolge = [], misserfolge = foundry.utils.deepClone(daten.misserfolge || []);

        for (const ziel of daten.ziele || []) {
            const targetActor = await ladeActor(ziel.actorUuid);
            const targetName = ziel.name || DSK_FW.ResolveTokenName(targetActor) || "Unbekanntes Ziel";

            if (!targetActor || !istLebewesen(targetActor)) {
                misserfolge.push({ name: targetName });
                continue;
            }

            const aktuelleSchips = leseVerfuegbareSchips(targetActor, casterActor.uuid);
            const tatsaechlicherVerlust = aktuelleSchips > 0
                ? Math.min(schipVerlust, aktuelleSchips)
                : Math.max(0, Number(ziel.tatsaechlicherVerlust) || 0);

            if (tatsaechlicherVerlust <= 0) {
                misserfolge.push({ name: targetName });
                continue;
            }

            try {
                const ok = await wendeEffekteAn({ casterActor, targetActor, qs, tatsaechlicherVerlust });
                if (ok) {
                    erfolge.push({ name: `${targetName} (−${tatsaechlicherVerlust} Schips)`, rolle: "Verfluchtes Ziel" });
                } else {
                    misserfolge.push({ name: targetName });
                }
            } catch (error) {
                console.error("Schwarze Katze: Effektanlage fehlgeschlagen.", { ziel, error });
                misserfolge.push({ name: targetName });
            }
        }

        const erfolgreich = erfolge.length > 0;

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId: daten.messageId,
            gabenName: vollerName,
            ahne,
            beschreibung: daten.beschreibung || beschreibungFuer(casterName, qs, schipVerlust),
            wirkender: casterName,
            ziele: erfolge,
            misserfolge,
            dauerText,
            erfolgreich
        });

        if (erfolgreich) {
            ui.notifications.info(
                `Luna sagt 🌙: Schwarze Katze wurde auf ${erfolge.length} Ziel(e) angewendet.`
            );
        } else {
            ui.notifications.error(
                "Luna sagt 🌙: Schwarze Katze konnte auf kein Ziel angewendet werden!"
            );
        }

        return true;
    };

    // +++ 6 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++++++
    if (game.user.isGM) {
        const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

        if (anfragen.length) {
            for (const anfrageActor of anfragen) {
                const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
                if (!daten) continue;

                if (await verarbeiteAnfrage(anfrageActor, daten)) {
                    await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
                }
            }

            return;
        }
    }

    // +++ 7 - WIRKENDER +++++++++++++++++++++++++++++++++++++++++++
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor).find(actor =>
                actor?.getFlag("world", "letzteGabenQS") !== undefined
            ) ||
            game.actors.find(actor =>
                actor.getFlag("world", "letzteGabenQS") !== undefined
            ) ||
            null;
    }

    if (!casterActor) {
        return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");
    }

    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
        );
    }

    const casterToken = DSK_FW.Token.Finde(casterActor);
    if (!casterToken) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!"
        );
    }

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    // +++ 8 - QS ++++++++++++++++++++++++++++++++++++++++++++++++++
    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor,
        gabenName,
        suchbegriffe: ["Schwarze Katze Probe", "Schwarze Katze"],
        testDataObj: typeof testData !== "undefined" ? testData : null,
        fallback: 0,
        protokollieren: true
    });

    if (qs <= 0) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName,
            ahne,
            beschreibung: "Der Pechfluch der Schwarzen Katze konnte nicht gewoben werden.",
            wirkender: casterName,
            ziele: [],
            misserfolge: [{ name: casterName }],
            dauerText: "Keine Wirkung",
            gmBereich: false,
            angewendet: true,
            erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 9 - ALLE TARGETS PRÜFEN (KEIN ZIEL-LIMIT, LEBEWESEN IN 4 SCHRITT MIT >= 1 SCHIP) +++
    const targets = Array.from(game.user.targets || []);

    if (!targets.length) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn(
            "Luna sagt 🌙: Bitte wähle mindestens ein Ziel per Target aus!"
        );
    }

    const schipVerlust = Math.max(1, Math.round(qs / 2));
    const gueltigeZiele = [];
    const misserfolge = [];

    for (const tToken of targets) {
        const tActor = tToken?.actor;
        const tName = tToken?.name || tActor?.name || "Unbekanntes Ziel";

        if (!tActor || !istLebewesen(tActor)) {
            misserfolge.push({ name: tName });
            continue;
        }

        const distanz = Math.round(DSK_FW.Geometrie.Distanz(casterToken, tToken) * 10) / 10;
        if (distanz > 4) {
            misserfolge.push({ name: tName });
            continue;
        }

        const schips = leseVerfuegbareSchips(tActor, casterActor.uuid);
        if (schips <= 0) {
            misserfolge.push({ name: tName });
            continue;
        }

        // Hat das Ziel mindestens 1 Schip, aber weniger als schipVerlust, verliert es genau seine vorhandenen Schips
        const tatsaechlicherVerlust = Math.min(schipVerlust, schips);

        gueltigeZiele.push({
            actorUuid: tActor.uuid,
            tokenId: tToken.id,
            tokenUuid: tToken.document?.uuid || tToken.uuid || null,
            name: tName,
            tatsaechlicherVerlust
        });
    }

    const beschreibung = beschreibungFuer(casterName, qs, schipVerlust);

    if (!gueltigeZiele.length) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName,
            ahne,
            beschreibung,
            wirkender: casterName,
            ziele: [],
            misserfolge,
            dauerText: "Keine Wirkung",
            gmBereich: false,
            angewendet: true,
            erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 10 - KARTE + GM-BUTTON ++++++++++++++++++++++++++++++++++
    const gmLink = DSK_FW.GabenUI.GMMakroButton(
        macroUuid,
        "Effekt anwenden",
        "Das Makro muss durch die Spielleitung ausgeführt werden."
    );

    const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName,
        ahne,
        beschreibung,
        wirkender: casterName,
        ziele: gueltigeZiele.map(z => ({
            name: `${z.name} (−${z.tatsaechlicherVerlust} Schips)`,
            rolle: "Verfluchtes Ziel"
        })),
        misserfolge,
        dauerText,
        gmLink,
        gmBereich: !game.user.isGM,
        anfragenderUserId: game.user.id
    });

    if (!nachricht) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error(
            "Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!"
        );
    }

    const anfrageDaten = {
        casterUuid: casterActor.uuid,
        casterName,
        casterTokenId: casterToken.id,
        casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
        ziele: gueltigeZiele,
        misserfolge,
        qs,
        beschreibung,
        sceneId: canvas.scene?.id || null,
        requestedByUserId: game.user.id,
        messageId: nachricht.id,
        macroUuid,
        erstellt: Date.now()
    };

    // +++ 11 - DIREKT ODER GM-ANFRAGE +++++++++++++++++++++++++++++
    if (game.user.isGM) {
        await verarbeiteAnfrage(casterActor, anfrageDaten);
        await raeumeQSAuf(casterActor);
        return;
    }

    await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);
    await raeumeQSAuf(casterActor);

    ui.notifications.info(
        "Luna sagt 🌙: Schwarze Katze wurde bei der Spielleitung zur Anwendung beantragt."
    );
}).call(this);
